alter table public.together_discovery_profiles add column photo_path text check(photo_path is null or char_length(photo_path) between 3 and 200);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('together-avatars','together-avatars',true,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=2097152,allowed_mime_types=excluded.allowed_mime_types;
create policy "together avatar insert own" on storage.objects for insert to authenticated with check(bucket_id='together-avatars' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "together avatar update own" on storage.objects for update to authenticated using(bucket_id='together-avatars' and owner_id=(select auth.uid())::text) with check(bucket_id='together-avatars' and owner_id=(select auth.uid())::text);
create policy "together avatar delete own" on storage.objects for delete to authenticated using(bucket_id='together-avatars' and owner_id=(select auth.uid())::text);

drop function public.together_my_discovery_profile();
create function public.together_my_discovery_profile() returns table(display_name text,city text,bio text,interests text[],visible boolean,photo_path text) language sql security definer set search_path='' stable as $$select p.display_name,p.city,p.bio,p.interests,p.visible,p.photo_path from public.together_discovery_profiles p where p.user_id=auth.uid()$$;
drop function public.together_save_discovery_profile(jsonb);
create function public.together_save_discovery_profile(p_profile jsonb) returns void language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();i text[];path text:=nullif(btrim(p_profile->>'photo_path'),'');begin if u is null then raise exception 'authentication required' using errcode='42501';end if;if path is not null and path not like u::text||'/%' then raise exception 'invalid photo path' using errcode='42501';end if;select coalesce(array_agg(distinct btrim(value)) filter(where btrim(value)<>''),'{}') into i from jsonb_array_elements_text(coalesce(p_profile->'interests','[]'::jsonb));insert into public.together_discovery_profiles(user_id,display_name,city,bio,interests,visible,photo_path,updated_at) values(u,btrim(p_profile->>'display_name'),btrim(p_profile->>'city'),btrim(p_profile->>'bio'),i,coalesce((p_profile->>'visible')::boolean,true),path,now()) on conflict(user_id) do update set display_name=excluded.display_name,city=excluded.city,bio=excluded.bio,interests=excluded.interests,visible=excluded.visible,photo_path=excluded.photo_path,updated_at=now();end$$;
drop function public.together_discovery_cards(integer,text,text);
create function public.together_discovery_cards(p_limit integer default 20,p_city text default '',p_interest text default '') returns table(display_name text,city text,bio text,interests text[],photo_path text) language sql security definer set search_path='' stable as $$select p.display_name,p.city,p.bio,p.interests,p.photo_path from public.together_discovery_profiles p where auth.uid() is not null and p.visible and p.user_id<>auth.uid() and (btrim(p_city)='' or lower(p.city)=lower(btrim(p_city))) and (btrim(p_interest)='' or exists(select 1 from unnest(p.interests) i where lower(i)=lower(btrim(p_interest)))) and not exists(select 1 from public.together_swipes s where s.actor_id=auth.uid() and s.target_id=p.user_id) and not exists(select 1 from public.together_blocks b where (b.blocker_id=auth.uid() and b.blocked_id=p.user_id) or (b.blocker_id=p.user_id and b.blocked_id=auth.uid())) order by p.updated_at desc limit least(greatest(coalesce(p_limit,20),1),50)$$;
drop function public.together_my_matches();
create function public.together_my_matches() returns table(match_id uuid,display_name text,city text,bio text,interests text[],photo_path text,matched_at timestamptz) language sql security definer set search_path='' stable as $$select m.id,p.display_name,p.city,p.bio,p.interests,p.photo_path,m.created_at from public.together_matches m join public.together_discovery_profiles p on p.user_id=case when m.user_a=auth.uid() then m.user_b else m.user_a end where auth.uid() is not null and (m.user_a=auth.uid() or m.user_b=auth.uid()) and not exists(select 1 from public.together_blocks b where (b.blocker_id=m.user_a and b.blocked_id=m.user_b) or (b.blocker_id=m.user_b and b.blocked_id=m.user_a)) order by m.created_at desc$$;
revoke all on function public.together_my_discovery_profile(),public.together_save_discovery_profile(jsonb),public.together_discovery_cards(integer,text,text),public.together_my_matches() from public,anon;
grant execute on function public.together_my_discovery_profile(),public.together_save_discovery_profile(jsonb),public.together_discovery_cards(integer,text,text),public.together_my_matches() to authenticated;
